INSERT INTO `creature_display_info_addon__new` (`display_id`, `bounding_radius`, `combat_reach`, `speed_walk`, `speed_run`, `display_id_other_gender`) SELECT `display_id`, `bounding_radius`, `combat_reach`, `speed_walk`, `speed_run`, `display_id_other_gender` FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY `display_id` ORDER BY `build` DESC, rowid DESC) AS __rn FROM `creature_display_info_addon` WHERE `build` <= 5875) WHERE __rn = 1;
DROP TABLE `creature_display_info_addon`;
ALTER TABLE `creature_display_info_addon__new` RENAME TO `creature_display_info_addon`;
CREATE TABLE `transports__new`( `entry` INTEGER NOT NULL DEFAULT 0, `name` TEXT COLLATE NOCASE, `period` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`entry`));
INSERT INTO `transports__new` (`entry`, `name`, `period`) SELECT `entry`, `name`, `period` FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY `entry` ORDER BY `build` DESC, rowid DESC) AS __rn FROM `transports` WHERE `build` <= 5875) WHERE __rn = 1;
DROP TABLE `transports`;
ALTER TABLE `transports__new` RENAME TO `transports`;
